\\ \\{{{B \xrightarrow[p7]{{\mathrm{\scriptsize~ 1 ~}}} a b}}} & {{{C \xrightarrow[p8]{{\mathrm{\scriptsize~ 0. 5 ~}}} a}}} & {{{C \xrightarrow[p9]{{\mathrm{\scriptsize~ 0. 2 ~}}} a a}}} \\ \end{array}
